app.get("/api/admin/overview",admin,async(req,res,next)=>{try{const [userCount,suspendedCount,noteCount,accounts]=await Promise.all([users.countDocuments(),users.countDocuments({isSuspended:true}),notes.countDocuments(),users.aggregate([{$lookup:{from:"notes",let:{accountId:{$toString:"$_id"}},pipeline:[{$match:{$expr:{$eq:["$userId","$$accountId"]}}},{$project:{noteBytes:{$add:[{$strLenBytes:{$ifNull:["$title",""]}},{$strLenBytes:{$ifNull:["$body",""]}},{$strLenBytes:{$ifNull:["$content",""]}},{$reduce:{input:{$ifNull:["$tags",[]]},initialValue:2,in:{$add:["$$value",{$strLenBytes:"$$this"},2,{$cond:[{$gt:["$$value",2]},1,0]}]}}},{$multiply:[{$size:{$ifNull:["$attachments",[]]}},24]}]}}}],as:"userNotes"}},{$lookup:{from:"noteImages.files",let:{accountId:{$toString:"$_id"}},pipeline:[{$match:{$expr:{$eq:["$metadata.userId","$$accountId"]}}},{$group:{_id:null,bytes:{$sum:"$length"}}}],as:"userImages"}},{$lookup:{from:"noteFiles.files",let:{accountId:{$toString:"$_id"}},pipeline:[{$match:{$expr:{$eq:["$metadata.userId","$$accountId"]}}},{$group:{_id:null,bytes:{$sum:"$length"}}}],as:"userFiles"}},{$addFields:{noteCount:{$size:"$userNotes"},storageUsedBytes:{$add:[{$sum:"$userNotes.noteBytes"},{$ifNull:[{$arrayElemAt:["$userImages.bytes",0]},0]},{$ifNull:[{$arrayElemAt:["$userFiles.bytes",0]},0]}]},storageQuotaBytes:{$ifNull:["$storageQuotaBytes",DEFAULT_STORAGE_BYTES]}}},{$project:{passwordHash:0,resetTokenHash:0,resetTokenExpiresAt:0,userNotes:0,userImages:0,userFiles:0}},{$sort:{createdAt:-1}},{$limit:250}]).toArray()]);res.json({stats:{userCount,suspendedCount,noteCount,storageUsedBytes:accounts.reduce((total,account)=>total+account.storageUsedBytes,0)},accounts:accounts.map(u=>({id:u._id.toString(),fullName:u.fullName||"",email:u.email,createdAt:u.createdAt,isSuspended:Boolean(u.isSuspended),noteCount:u.noteCount,storageUsedBytes:u.storageUsedBytes,storageQuotaBytes:isAdmin(u)?null:u.storageQuotaBytes,isAdmin:isAdmin(u)}))})}catch(x){next(x)}});
app.patch("/api/admin/accounts/:id",same,admin,async(req,res,next)=>{try{const id=req.params.id,action=req.body.action;if(!ObjectId.isValid(id)||!["suspend","restore"].includes(action))return res.status(400).json({error:"Invalid account action."});const target=await users.findOne({_id:new ObjectId(id)});if(!target)return res.status(404).json({error:"Account not found."});if(isAdmin(target))return res.status(403).json({error:"The configured administrator account cannot be suspended."});await users.updateOne({_id:target._id},{$set:{isSuspended:action==="suspend"}});res.status(204).end()}catch(x){next(x)}});
app.delete("/api/admin/accounts/:id",same,admin,async(req,res,next)=>{try{const id=req.params.id;if(!ObjectId.isValid(id))return res.status(400).json({error:"Invalid account."});const target=await users.findOne({_id:new ObjectId(id)});if(!target)return res.status(404).json({error:"Account not found."});if(isAdmin(target))return res.status(403).json({error:"The configured administrator account cannot be deleted."});if(target.stripeSubscriptionId&&["active","trialing","past_due"].includes(target.stripeSubscriptionStatus)){if(!stripe)return res.status(503).json({error:"Configure Stripe before deleting an account with an active subscription."});await stripe.subscriptions.cancel(target.stripeSubscriptionId)}await Promise.all([notes.deleteMany({userId:id}),shares.deleteMany({userId:id})]);await Promise.all([removeAllNoteImages(id),removeAllNoteFiles(id)]);await users.deleteOne({ _id: target._id });res.status(204).end()}catch(x){next(x)}});
const adminPage=async(req,res,next)=>{try{if(!req.session.userId||!ObjectId.isValid(req.session.userId))return res.redirect("/sign-in.html?next="+encodeURIComponent(req.originalUrl));const account=await users.findOne({_id:new ObjectId(req.session.userId)});if(!account||account.isSuspended)return res.redirect("/sign-in.html");if(!isAdmin(account))return res.status(403).type("text").send("Administrator access is required.");req.account=account;next()}catch(error){next(error)}};
