app.get(["/","/index.html"],(req,res)=>res.sendFile(publicFile("index.html"),{headers:{"Cache-Control":"no-cache"}}));for(const p of ["favicon.svg","icon-192.png","icon-512.png","icon-maskable-192.png","icon-maskable-512.png","offline.html","memorykeepnote.html","shared-note.html","sign-in.html","sign-up.html","forgot-password.html","reset-password.html","admin.html","site-content.js"])app.get("/"+p,(req,res)=>res.sendFile(publicFile(p),{headers:p==="shared-note.html"?{"Cache-Control":"no-store"}:p==="site-content.js"?{"Cache-Control":"no-cache"}:undefined}));app.use((x,req,res,next)=>{console.error(x);const status=x?.type==="entity.too.large"?413:500,message=status===413?(req.path.includes("/attachments")?"Attachments must be 20 MB or smaller.":"Image files must be 5 MB or smaller."):"Something went wrong. Please try again.";res.status(status).json({error:message})});
function describeMongoUri(){try{const uri=new URL(mongoUri);return {scheme:uri.protocol,host:uri.hostname,database:uri.pathname.replace(/^\//,"")||"(default)",hasUsername:Boolean(uri.username),hasPassword:Boolean(uri.password),usesSrv:uri.protocol==="mongodb+srv:"}}catch{return {scheme:"invalid"}}}
function connectionSummary(error){const code=error?.cause?.code||error?.code||"unknown",message=String(error?.cause?.message||error?.message||"").replace(/mongodb(?:\+srv)?:\/\/[^\s]+/gi,"[redacted MongoDB URI]");return {code,message:message.slice(0,500)}}
async function diagnoseSrv(){const details=describeMongoUri();console.info("MongoDB startup diagnostics:",{node:process.version,openssl:process.versions.openssl,...details});if(details.usesSrv){try{const records=await dns.promises.resolveSrv("_mongodb._tcp."+details.host);console.info("MongoDB SRV DNS lookup succeeded.",{records:records.length})}catch(error){console.error("MongoDB SRV DNS lookup failed.",{code:error.code||"unknown",message:String(error.message).slice(0,300)})}}}
async function connectWithRetry(){await diagnoseSrv();let lastError;for(let attempt=1;attempt<=4;attempt++){try{await mongo.connect();await mongo.db("admin").command({ping:1});console.info("MongoDB connection established.");return}catch(error){lastError=error;console.error("MongoDB connection attempt failed.",{attempt,maxAttempts:4,...connectionSummary(error)});if(attempt<4)await new Promise(resolve=>setTimeout(resolve,attempt*2000));try{await mongo.close()}catch{}}}throw lastError}
async function start(){await connectWithRetry();const db=mongo.db();users=db.collection("users");notes=db.collection("notes");folders=db.collection("folders");shares=db.collection("noteShares");siteContent=db.collection("siteContent");billingPlans=db.collection("billingPlans");billingEvents=db.collection("billingEvents");await billingPlans.updateOne({_id:PLUS_PLAN_ID},{$setOnInsert:{name:"Plus",enabled:false,storageQuotaBytes:20*1024**3,features:[...PAID_FEATURES],priceAmounts:{monthly:2000,yearly:24000},stripeProductId:null,stripePriceIds:{},createdAt:new Date()}},{upsert:true});imageBucket=new GridFSBucket(db,{bucketName:"noteImages"});noteFileBucket=new GridFSBucket(db,{bucketName:"noteFiles"});await Promise.all([notes.dropIndex("userId_1_noteId_1").catch(()=>{}),folders.dropIndex("userId_1_folderId_1").catch(()=>{})]);await Promise.all([users.createIndex({email:1},{unique:true}),users.createIndex({resetTokenExpiresAt:1},{expireAfterSeconds:0}),notes.createIndex({userId:1,"id":1},{unique:true}),notes.createIndex({userId:1,updated:-1}),notes.createIndex({userId:1,tags:1}),folders.createIndex({userId:1,"id":1},{unique:true}),shares.createIndex({userId:1,noteId:1},{unique:true}),shares.createIndex({tokenHash:1},{unique:true}),billingEvents.createIndex({receivedAt:1},{expireAfterSeconds:7776000}),db.collection("noteImages.files").createIndex({"metadata.userId":1,"metadata.noteId":1}),db.collection("noteFiles.files").createIndex({"metadata.userId":1,"metadata.noteId":1})]);app.listen(PORT,HOST,()=>console.log(`Memory Keep Note listening on http://${HOST}:${PORT}`))}start().catch(error=>{console.error("MongoDB startup failed after retries.",connectionSummary(error));process.exit(1)});
